      "id": "P4",
      "text": "Indication: Dilated common bile duct on abdominal ultrasound; evaluate for choledocholithiasis."
    },
    {
      "id": "P5",
      "text": "Procedure: The linear echoendoscope was advanced to the second portion of the duodenum."
    },
    {
      "id": "P6",
      "text": "EUS imaging was performed from the esophagus, stomach and duodenum."
    },
    {
      "id": "P7",
      "text": "Findings: common bile duct 7 mm without stones or sludge; the ampulla was normal."
    },
    {
      "id": "P8",
      "text": "Fine-needle aspiration was not performed because no target lesion was found."
    },
    {
      "id": "P9",
      "text": "Impression: Mildly dilated common bile duct without choledocholithiasis on EUS."
    },
    {
      "id": "P10",
      "text": "Plan: Clinic follow-up with repeat liver tests."
    }
